    private void testSnsGenProbeCheckIfPhoneNumberIsOptedOut(TestContext t) {
        GROUP_SNS_GEN_PROBE.runTest(t, "CheckIfPhoneNumberIsOptedOut",
                new Call("CheckIfPhoneNumberIsOptedOut", "{\"phoneNumber\":\"+12025550100\"}",
                        b -> CheckIfPhoneNumberIsOptedOutRequest.builder()
                                .phoneNumber("+12025550100")
                                .build(),
                        r -> cl().checkIfPhoneNumberIsOptedOut((CheckIfPhoneNumberIsOptedOutRequest) r)),
                List.of(
                        Clause.responseField(
                                Check.nonEmpty("$.isOptedOut")
                        )
                ));
    }

